function claudeInstallUrl(){const u=new URL('https://claude.ai/customize/connectors');u.searchParams.set('modal','add-custom-connector');u.searchParams.set('connectorName',env().PUBLIC_BRAND_NAME);u.searchParams.set('connectorUrl',`${env().PUBLIC_BASE_URL}/mcp`);return u.toString();}
function siteShell(body:string,title=env().PUBLIC_BRAND_NAME,path='/'){const supportEmail=env().SUPPORT_EMAIL?.trim();const description=`Make supported public links AI-readable. ${env().PUBLIC_BRAND_NAME} turns videos, social posts, discussions, webpages, developer threads and text-layer PDFs into usable source context for the AI you already use.`;const base=env().PUBLIC_BASE_URL.replace(/\/$/,'');const canonical=`${base}${path.startsWith('/')?path:`/${path}`}`;return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>${title}</title><meta name="description" content="${description}"><meta name="robots" content="index,follow"><meta name="theme-color" content="#fbfaf8"><link rel="canonical" href="${canonical}"><meta property="og:type" content="website"><meta property="og:site_name" content="${env().PUBLIC_BRAND_NAME}"><meta property="og:title" content="${title}"><meta property="og:description" content="${description}"><meta property="og:url" content="${canonical}"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="${title}"><meta name="twitter:description" content="${description}"><link rel="icon" href="/logo.svg"><script type="application/ld+json">${JSON.stringify({"@context":"https://schema.org","@type":"SoftwareApplication",name:env().PUBLIC_BRAND_NAME,applicationCategory:"ProductivityApplication",operatingSystem:"Web",url:base,description})}</script><style>${siteCss}</style></head><body><a class="skip-link" href="#main-content">Skip to content</a><div class="wrap"><nav aria-label="Primary"><a class="brand" href="/" aria-label="${env().PUBLIC_BRAND_NAME} home"><img src="/logo.svg" alt=""><span>${env().PUBLIC_BRAND_NAME}</span></a><div class="navlinks"><a class="hide-sm" href="/#examples">What you can do</a><a class="hide-sm" href="/#how">How it works</a><a class="hide-sm" href="/#supported">Supported links</a><a class="hide-sm" href="/#faq">FAQ</a><a class="hide-sm" href="/pricing">Pricing</a><details class="mobile-menu"><summary aria-label="Open navigation">Menu</summary><div class="mobile-menu-panel"><a href="/#examples">What you can do</a><a href="/#how">How it works</a><a href="/#context">What your AI gets</a><a href="/#supported">Supported links</a><a href="/#faq">FAQ</a><a href="/pricing">Pricing</a><a href="/support">Support</a><a href="/account">Account</a></div></details><a class="btn sm purple" href="/connect">Connect free</a></div></nav>${body}<footer><span>© 2026 ${env().PUBLIC_BRAND_NAME}</span><span class="legal-links"><a href="/privacy">Privacy</a> · <a href="/terms">Terms</a> · <a href="/status">Status</a> · <a href="/support">Support</a> · <a href="/account">Account</a>${supportEmail?` · <a href="mailto:${supportEmail}">${supportEmail}</a>`:''}</span></footer></div></body></html>`;}

app.get('/',async(req,reply)=>{await trackWebsiteVisit(req,reply,'/');return reply.type('text/html').send(siteShell(`<main id="main-content"><section class="hero"><div class="hero-grid"><div><span class="badge"><span class="badge-dot"></span>V2 · public links → readable source context</span><h1>Paste the link.<br><em>Your AI can read it.</em></h1><p>When Claude cannot reliably access what is behind a public link, ${env().PUBLIC_BRAND_NAME} reads the useful source content and gives it back as clean context. Paste the link, ask your normal question, and keep the conversation in Claude.</p><div class="actions"><a class="btn purple" href="/connect">Connect to Claude — free →</a><a class="btn alt" href="/#examples">See what you can do</a></div><div class="micro">10-unit free trial · No card · No social-media passwords · Failed or unsupported reads use 0 processing units</div><div class="platforms"><span class="platform"><b></b>YouTube</span><span class="platform"><b></b>TikTok</span><span class="platform"><b></b>Instagram</span><span class="platform"><b></b>X</span><span class="platform"><b></b>Reddit</span><span class="platform"><b></b>Bluesky</span><span class="platform"><b></b>GitHub</span><span class="platform"><b></b>Hacker News</span><span class="platform"><b></b>Web / PDF</span></div><div class="clarity-strip"><div class="clarity-item"><b>1</b><div><strong>You paste a public link</strong><span>Keep using the same Claude conversation.</span></div></div><div class="clarity-item"><b>2</b><div><strong>Link2AI reads the source</strong><span>It chooses the right reader for video, post, thread, page, developer discussion or document.</span></div></div><div class="clarity-item"><b>3</b><div><strong>Claude answers your question</strong><span>Claude still does the reasoning, not Link2AI.</span></div></div></div></div><div class="demo"><div class="demo-window"><div class="window-top"><span class="window-dot"></span><span class="window-dot"></span><span class="window-dot"></span><span class="window-title">Claude + ${env().PUBLIC_BRAND_NAME}</span></div><div class="chat"><div class="chat-row user">https://reddit.com/r/…<br>Read this thread. What are the main viewpoints?</div><div class="tool-card"><div class="tool-head"><div class="tool-name"><span class="tool-icon">↗</span>Read link content</div><span class="tool-state">ready</span></div><div class="tool-line w82"></div><div class="tool-line w57"></div></div><div class="chat-row ai">The discussion splits into two main views… Here is where commenters agree and disagree.</div></div></div></div></div></section><section class="section" id="examples"><div class="section-head"><div><div class="section-index">01 · What you can do</div><h2>Ask about the source, not just the URL.</h2></div><p class="sub">The value is not “another summarizer”. It is giving your AI enough source context to answer the question you actually care about.</p></div><div class="use-grid"><div class="use-card"><div class="eyebrow">Video</div><h3>Check what was actually said</h3><p>Use spoken or caption text as context instead of hunting for transcripts and copying them into chat.</p><div class="example-prompt">“What does the speaker claim in this video, and which claims should I verify?”</div></div><div class="use-card"><div class="eyebrow">Social / discussion</div><h3>Understand the conversation</h3><p>Bring a public post, story or useful discussion context into the same conversation without pretending an unlimited thread was fully read.</p><div class="example-prompt">“What are the main viewpoints here, and where do people disagree?”</div></div><div class="use-card"><div class="eyebrow">Article / document</div><h3>Question the source directly</h3><p>Let Claude work from readable article, webpage or text-layer PDF content instead of guessing from a title, snippet or filename.</p><div class="example-prompt">“What evidence does this source give for its main conclusion?”</div></div><div class="use-card"><div class="eyebrow">Developer work</div><h3>Read the issue or PR discussion</h3><p>Give Claude the public GitHub issue or pull-request context it needs to explain decisions, disagreements and next steps.</p><div class="example-prompt">“Summarize this PR, the reviewer concerns, and what still needs to change.”</div></div></div></section><section class="section" id="how"><div class="section-head"><div><div class="section-index">02 · How it works</div><h2>Connect once. Then use Claude normally.</h2></div><p class="sub">You do not need to learn MCP or change how you ask questions. Link2AI sits behind the conversation and steps in only when source access is needed.</p></div><div class="step-grid"><div class="step-card"><div class="flow-num">1</div><h3>Connect Link2AI once</h3><p>Use the guided Claude setup. The founding trial does not require a card.</p></div><div class="step-card"><div class="flow-num">2</div><h3>Paste a link + your question</h3><p>No upload workflow and no special command. Ask the question you were going to ask anyway.</p></div><div class="step-card"><div class="flow-num">3</div><h3>Link2AI retrieves source context</h3><p>It selects the appropriate reader and avoids running when Claude already has enough context.</p></div><div class="step-card"><div class="flow-num">4</div><h3>Claude does the thinking</h3><p>Claude summarizes, compares, translates, checks or answers using the returned source context.</p></div></div><div class="trust-row"><span class="trust-pill">Public content only</span><span class="trust-pill">No separate Link2AI chatbot</span><span class="trust-pill">Temporary source cache</span><span class="trust-pill">Failed or unsupported reads use 0 processing units</span></div></section><section class="section" id="context"><div class="section-head"><div><div class="section-index">03 · What your AI gets</div><h2>Not just text. Context with a completeness signal.</h2></div><p class="sub">A successful read returns the useful source content plus metadata that tells the AI what it read, how much was processed, and whether the source was only partially read.</p></div><div class="context-grid"><div class="context-copy"><h3>Why this matters for answer quality</h3><p>Reading a link is only useful if the AI knows when the source is incomplete. Link2AI carries completeness metadata through cache, API and MCP instead of silently treating a truncated source as complete.</p><div class="context-points"><div class="context-point"><b>1</b><span><strong>Source type and canonical URL</strong><br>so the AI knows what kind of source it is working from.</span></div><div class="context-point"><b>2</b><span><strong>Extracted content + counts when known</strong><br>such as processed pages or discussion items.</span></div><div class="context-point"><b>3</b><span><strong>Explicit truncation warning</strong><br>so the AI can qualify its answer or tell you that it did not see the whole source.</span></div></div></div><div class="context-packet"><div class="packet-head"><span class="packet-title">Example source context</span><span class="packet-state">processed</span></div><div class="packet-row"><span class="packet-key">Source</span><span class="packet-value">GitHub pull request</span></div><div class="packet-row"><span class="packet-key">Content</span><span class="packet-value">Title, description, review discussion and bounded diff context</span></div><div class="packet-row"><span class="packet-key">Completeness</span><span class="packet-value">Partial · diff exceeded the safe content budget</span></div><div class="packet-row"><span class="packet-key">Usage</span><span class="packet-value">Only the successfully processed content counts</span></div><div class="packet-warning"><strong>Note to the AI:</strong> Link2AI processed only part of this source because it exceeded the safe content limit. Do not imply the full source was reviewed.</div></div></div></section><section class="section" id="supported"><div class="section-head"><div><div class="section-index">04 · What it reads today</div><h2>One link. The right reader behind it.</h2></div><p class="sub">Different sources need different extraction paths. Link2AI routes supported URLs instead of pretending every page can be handled the same way.</p></div><div class="source-grid"><div class="source-card"><div class="source-icon">▶</div><h3>Video</h3><p>For public video links, Link2AI prefers publisher captions and can fall back to speech-to-text when usable captions are unavailable.</p><div class="source-tags"><span>YouTube</span><span>Shorts</span><span>TikTok video</span><span>Instagram Reel</span></div></div><div class="source-card"><div class="source-icon">#</div><h3>Social & discussions</h3><p>For supported public posts and discussions, Link2AI extracts the useful text and keeps long threads bounded instead of silently implying it read everything.</p><div class="source-tags"><span>Instagram</span><span>X</span><span>Reddit</span><span>Bluesky</span><span>Hacker News</span><span>TikTok post</span></div></div><div class="source-card"><div class="source-icon">↗</div><h3>Articles & documents</h3><p>Readable public HTTPS pages are reduced to useful page text. Public PDFs are supported when they contain a usable text layer; scanned image-only PDFs are not OCRed in this release.</p><div class="source-tags"><span>Articles</span><span>News</span><span>Blogs</span><span>Public webpages</span><span>Text-layer PDF</span></div></div><div class="source-card"><div class="source-icon">&lt;/&gt;</div><h3>Developer discussions</h3><p>Public GitHub issues and pull requests can be read as source context, including discussion and bounded PR-diff context when available.</p><div class="source-tags"><span>GitHub Issue</span><span>GitHub PR</span><span>Review discussion</span><span>PR diff context</span></div></div></div><div class="scope-note"><div class="scope-icon">!</div><div><strong>The boundary is simple: individual public content, bounded processing, no private access or bulk crawling.</strong><p>Profiles, feeds, search pages, private/login-only content, paywalls, DRM-protected media and bulk site crawling are outside V2. Very large threads, pages, pull requests and documents may be partially processed; when that happens Link2AI tells the AI that the source was truncated instead of pretending it saw everything. Public PDFs currently require a usable text layer and are bounded to 100 processed pages / 12 MB.</p></div></div></section><section class="section" id="why"><div class="section-head"><div><div class="section-index">05 · Why it matters</div><h2>Stop doing the copy-paste work for your AI.</h2></div><p class="sub">Link2AI removes the dead end where the source exists but your AI cannot reliably read what is actually behind the link.</p></div><div class="compare-grid"><div class="compare-card"><div class="compare-title"><span class="compare-dot"></span>Without Link2AI</div><div class="compare-list"><div class="compare-row"><span class="compare-icon">1</span><span>You open the source and hunt for captions, post text or the useful part of a long page.</span></div><div class="compare-row"><span class="compare-icon">2</span><span>You copy chunks into chat, lose context, or settle for what the AI can infer from the URL.</span></div><div class="compare-row"><span class="compare-icon">3</span><span>The conversation starts from incomplete source context.</span></div></div></div><div class="compare-card good"><div class="compare-title"><span class="compare-dot"></span>With Link2AI</div><div class="compare-list"><div class="compare-row"><span class="compare-icon">1</span><span><strong>Paste the public link</strong> in the AI conversation you were already using.</span></div><div class="compare-row"><span class="compare-icon">2</span><span><strong>Link2AI retrieves readable source context</strong> when the host AI actually needs it.</span></div><div class="compare-row"><span class="compare-icon">3</span><span><strong>Your AI does the thinking</strong> — summarize, compare, verify, translate or answer.</span></div></div></div></div></section><section class="section"><div class="section-head"><div><div class="section-index">06 · What it is — and is not</div><h2>A thin access layer, not another AI app.</h2></div><p class="sub">Keeping the job narrow makes the product easier to understand: retrieve source context safely, then get out of the way.</p></div><div class="boundary-grid"><div class="boundary-card good"><h3>Link2AI does</h3><div class="boundary-list"><div class="boundary-row"><i>✓</i><span>Read supported public links and return AI-readable source context.</span></div><div class="boundary-row"><i>✓</i><span>Normalize supported links and reuse temporary cached results when appropriate.</span></div><div class="boundary-row"><i>✓</i><span>Process captions, speech or public page/post text depending on the source.</span></div><div class="boundary-row"><i>✓</i><span>Count processing usage from content successfully returned to the AI, with 0 units for unsupported or failed reads and explicit truncation metadata for partial reads.</span></div></div></div><div class="boundary-card"><h3>Link2AI does not</h3><div class="boundary-list"><div class="boundary-row"><i>×</i><span>Replace Claude with a separate Link2AI chatbot.</span></div><div class="boundary-row"><i>×</i><span>Bypass private accounts, paywalls, DRM or other access controls.</span></div><div class="boundary-row"><i>×</i><span>Edit, publish or delete content on the source website.</span></div><div class="boundary-row"><i>×</i><span>Build a permanent library of scraped source content.</span></div></div></div></div></section><section class="section"><div class="section-head"><div><div class="section-index">07 · Pricing</div><h2>Try one real workflow before you pay.</h2></div><p class="sub">Start with the founding trial. Upgrade only if reading links inside your normal AI workflow is actually useful to you.</p></div><div class="pricing"><div class="price-card"><div class="price-name">Trial</div><div class="price">$0</div><ul class="list"><li>10 processing units</li><li>Same supported content types</li><li>No card required</li></ul></div><div class="price-card featured"><span class="price-badge">Most useful</span><div class="price-name">Basic</div><div class="price">$4.99 <small>/ month</small></div><ul class="list"><li>500 processing units / month</li><li>Same supported content types as Pro</li><li>Up to 30 minutes per video</li><li>2 concurrent jobs</li></ul></div><div class="price-card"><div class="price-name">Pro</div><div class="price">$9.99 <small>/ month</small></div><ul class="list"><li>2,000 processing units / month</li><li>Same supported content types as Basic</li><li>Up to 120 minutes per video</li><li>4 concurrent jobs</li></ul></div></div><div class="pricing-explainer"><div><strong>Text links</strong>Roughly 2,500 estimated tokens successfully returned to the AI = 1 processing unit. Successful reads use at least 1 unit.</div><div><strong>Video links</strong>Each started minute successfully processed = 1 processing unit, subject to the plan’s per-video limit.</div><div><strong>Failed / partial reads</strong>Unsupported, inaccessible, login-required, empty or failed reads use 0 units. Truncated reads charge only the content actually processed.</div></div><div class="unit-examples"><div class="unit-example"><strong>9-minute video → 9 units</strong><span>Video rounds up by started processed minute.</span></div><div class="unit-example"><strong>~1,800-token article → 1 unit</strong><span>Successful text reads have a 1-unit minimum.</span></div><div class="unit-example"><strong>~6,100-token thread → about 3 units</strong><span>Text usage scales with the amount actually processed, not the number of links.</span></div></div><div class="actions"><a class="btn purple" href="/connect">Start free →</a><a class="btn alt" href="/pricing">Compare plans</a></div></section><section class="section" id="faq"><div class="section-head"><div><div class="section-index">08 · Questions before you connect</div><h2>FAQ</h2></div><p class="sub">Start with the basics, then keep scrolling for content limits, privacy and billing details.</p></div><div class="faq-groups"><div class="faq-group"><div class="faq-group-title"><h3>Start here</h3><span>What it is, when it runs, and how to use it</span></div><div class="faq-list"><details class="faq-item"><summary>Why use Link2AI if Claude can already browse some links?</summary><div class="faq-answer"><p>Claude can access plenty of public information on its own. Link2AI is for the gaps: supported links whose actual video, post, comment thread or page content is not reliably available to the model. If Claude already has enough context, Link2AI should stay out of the way.</p></div></details><details class="faq-item"><summary>Does Link2AI run on every link I paste?</summary><div class="faq-answer"><p>No. The connector is designed to be called only when your request actually depends on content behind a supported link and the host AI does not already have sufficient access.</p></div></details><details class="faq-item"><summary>Do I need to say “use Link2AI” every time?</summary><div class="faq-answer"><p>No. After setup, the intended workflow is to paste a supported link and ask your normal question. Claude decides whether it needs Link2AI. The setup guide explains the one-time Tool access setting that makes this more reliable.</p></div></details><details class="faq-item"><summary>Does Link2AI answer or summarize the content itself?</summary><div class="faq-answer"><p>No. Link2AI supplies AI-readable source context. The host AI remains the chat interface and does the summarizing, comparing, reasoning, translating or fact-checking you asked for.</p></div></details><details class="faq-item"><summary>What about ChatGPT and other AI clients?</summary><div class="faq-answer"><p>Link2AI is built as an MCP access layer rather than a Claude-only product. V2 is Claude-first so onboarding and reliability stay focused on one client surface; ChatGPT remains a first-class target as distribution widens.</p></div></details><details class="faq-item"><summary>Can I ask about more than one link?</summary><div class="faq-answer"><p>Yes, the host AI can read supported links one at a time and use the returned source context together in the same conversation. Link2AI is not designed for bulk crawling entire sites, feeds or profile histories.</p></div></details></div></div><div class="faq-group"><div class="faq-group-title"><h3>Content & limits</h3><span>What can be read, what cannot, and how usage works</span></div><div class="faq-list"><details class="faq-item"><summary>What links are supported right now?</summary><div class="faq-answer"><p>V2 supports public YouTube and Shorts, TikTok video/posts, Instagram Reels and posts, individual X posts, Reddit posts/discussions, Bluesky posts, Hacker News discussions, readable public HTTPS webpages/articles, public GitHub issues and pull requests, and public PDFs with a usable text layer.</p></div></details><details class="faq-item"><summary>Can it read Reddit comments too?</summary><div class="faq-answer"><p>Yes. For a supported Reddit post, Link2AI can include public comments and replies within a bounded content budget. Very large discussions may be partially processed, and the returned source context should say when it was truncated instead of implying the entire thread was read.</p></div></details><details class="faq-item"><summary>Can it crawl a whole profile, feed or search page?</summary><div class="faq-answer"><p>No. The product is intentionally link-scoped. Profiles, feeds, timelines, search results and bulk crawling are outside V2.</p></div></details><details class="faq-item"><summary>What other content is not supported?</summary><div class="faq-answer"><p>Private/login-only content, deleted content, paywalled or DRM-protected media, and content blocked by access controls are not supported. Link2AI does not bypass those restrictions.</p></div></details><details class="faq-item"><summary>Can it read images, charts or image-only text?</summary><div class="faq-answer"><p>Not reliably yet. V2 focuses on spoken/caption text and public page/post text. Visual-only details such as diagrams, gestures, screenshots, image-only captions and before/after comparisons may be missing.</p></div></details><details class="faq-item"><summary>Can it read PDF files?</summary><div class="faq-answer"><p>Yes, when the public PDF contains a usable text layer. Link2AI extracts a bounded amount of text and should tell the AI if only part of a large document was processed. Scanned or image-only PDFs are not OCRed in this release and should not be treated as successfully read text.</p></div></details><details class="faq-item"><summary>What happens if a page, thread, PR or PDF is extremely large?</summary><div class="faq-answer"><p>Link2AI uses bounded processing limits so one source cannot consume unbounded time or memory. When only part of a large source is processed, the result should include a clear truncation warning and, when known, what portion was read. That lets the host AI avoid claiming it saw the complete source.</p></div></details><details class="faq-item"><summary>Can it read GitHub pull-request diffs and review discussion?</summary><div class="faq-answer"><p>Yes, for supported public pull requests. Link2AI prioritizes the PR title, description and discussion, then includes bounded diff context. If a diff is too large, the useful PR context can still be returned with a note that the diff was truncated.</p></div></details><details class="faq-item"><summary>How are videos processed?</summary><div class="faq-answer"><p>Link2AI prefers existing publisher/platform captions. When usable captions are unavailable, supported videos can fall back to temporary audio extraction and speech-to-text. Temporary media/audio files are deleted after processing.</p></div></details><details class="faq-item"><summary>Do failed or unsupported links use my quota?</summary><div class="faq-answer"><p>No. Unsupported, inaccessible, login-required, empty or failed extractions use 0 processing units. Internal retries should not double-charge the same job. Usage is finalized only for useful content that was successfully processed.</p></div></details><details class="faq-item"><summary>What is a processing unit?</summary><div class="faq-answer"><p>For video, each started minute of processed video is 1 unit. For text-based sources, Link2AI uses a deterministic size estimate and charges 1 unit for each roughly 2,500 estimated tokens successfully returned to the AI, with a minimum of 1 unit for a successful read. The estimate is for usage accounting; it is not an exact Claude or ChatGPT tokenizer count.</p></div></details><details class="faq-item"><summary>Is there a limit on how many links I can read?</summary><div class="faq-answer"><p>Basic and Pro are not limited by a fixed number of links. Usage is based on the amount of content successfully processed. A short post and a very large document therefore do not cost the same amount simply because each is one URL.</p></div></details><details class="faq-item"><summary>What happens when a source is larger than the safe processing limit?</summary><div class="faq-answer"><p>Link2AI returns the useful portion it could safely process and marks the result as truncated. The AI also receives a clear warning plus available item/page counts when they are known. Public PDFs are currently bounded to 100 processed pages and 12 MB; other long pages, discussions and pull requests use bounded text budgets.</p></div></details><details class="faq-item"><summary>How do I know whether Link2AI saw the whole source?</summary><div class="faq-answer"><p>Successful results carry completeness metadata. When a source is truncated, the AI receives an explicit warning and, when the platform exposes reliable counts, information such as pages or discussion items processed. This is designed to prevent a partial source from being presented as if it were complete.</p></div></details><details class="faq-item"><summary>How accurate is the extracted content?</summary><div class="faq-answer"><p>Link2AI aims to reproduce useful source text, not to reinterpret it. For video, publisher captions are preferred and speech-to-text may be used as a fallback, so transcription errors are possible. Web, discussion, GitHub and PDF reads depend on the public text the source exposes. Claude or another host AI still performs the reasoning, and important claims should be checked against the original source.</p></div></details><details class="faq-item"><summary>What are the current V2 safety limits?</summary><div class="faq-answer"><p>Current backend budgets are approximately 30,000 estimated tokens for webpages/articles, Reddit/Hacker News and GitHub Issues; 40,000 for GitHub pull requests; 50,000 plus 100 processed pages / 12 MB for text-layer PDFs; and 12,000 for short social-post content. Discussions and GitHub threads also have emergency item/depth caps. These are reliability safeguards and may be tuned as Link2AI gathers real production benchmark data.</p></div></details></div></div><div class="faq-group"><div class="faq-group-title"><h3>Privacy, permissions & billing</h3><span>What Link2AI stores and what access it does not need</span></div><div class="faq-list"><details class="faq-item"><summary>Do I need to give Link2AI my social-media passwords?</summary><div class="faq-answer"><p>No. Link2AI is designed around supported public links and does not need your Reddit, X, Instagram, TikTok or YouTube password to read public content. It does not ask you to hand over private-account credentials.</p></div></details><details class="faq-item"><summary>Does Link2AI edit, post or delete anything on those sites?</summary><div class="faq-answer"><p>No. It reads supported public content. Starting a read can create an internal processing job and reserve quota, which is why an AI client may show a write-style permission label, but Link2AI does not modify the source website or your social account.</p></div></details><details class="faq-item"><summary>How long is extracted content stored?</summary><div class="faq-answer"><p>Source text/transcript cache is temporary and currently defaults to 72 hours. Temporary downloaded media/audio is removed after processing, and stored source URLs/canonical identifiers are scrubbed after the configured content-retention window.</p></div></details><details class="faq-item"><summary>Does Link2AI store my IP address for website analytics?</summary><div class="faq-answer"><p>The first-party website analytics are designed without storing visitor IP addresses. A random first-party visitor token is used for website visitor/page-view measurement.</p></div></details><details class="faq-item"><summary>Can I manage or cancel a paid plan later?</summary><div class="faq-answer"><p>Yes. Paid-plan billing management is available from your Link2AI account through the subscription-management flow. You do not need to contact support just to open billing management.</p></div></details><details class="faq-item"><summary>Where do I go if a link should work but does not?</summary><div class="faq-answer"><p>Use the <a href="/support">Support page</a>. Include the platform, public URL, error message and job ID if one is shown. Never send passwords, private-account credentials or payment details.</p></div></details></div></div></div><div class="actions" style="margin-top:30px"><a class="btn purple" href="/connect">Connect to Claude — free →</a><a class="btn alt" href="/support">Support</a></div></section><section class="section"><div class="cta-band"><div><h2>Keep the conversation. Lose the link-reading friction.</h2><p>Connect once, then paste supported public links into Claude and ask the question you actually wanted to ask.</p></div><div class="actions"><a class="btn purple" href="/connect">Connect Link2AI — free →</a><a class="btn alt" href="/pricing">See pricing</a></div></div></section></main>`, `${env().PUBLIC_BRAND_NAME} — Make public links readable by Claude`, `/`));});

app.get('/connect',async(req,reply)=>{await trackWebsiteVisit(req,reply,'/connect');const install=claudeInstallUrl().replace(/&/g,'&amp;');return reply.type('text/html').send(siteShell(`<main id="main-content"><section class="connect-hero"><span class="badge"><span class="badge-dot"></span>Claude-first V2</span><h1>Install once. Then just paste links.</h1><p>You do not need to understand MCP, OAuth, client IDs or API keys. Follow the four steps below and Claude can call ${env().PUBLIC_BRAND_NAME} when it actually needs the content behind a supported link.</p><div class="guide-status"><span>About 2 minutes</span><span>Email account</span><span>No card</span><span>No client secret</span></div></section><section class="setup-shell"><div class="setup-main"><h2>Start here: open the pre-filled Claude setup.</h2><p>You will move between this page and Claude once. The four cards below are the entire setup; each one explains exactly what to click and why.</p><div class="setup-cta"><a class="btn purple" id="claude-install" href="${install}" target="_blank" rel="noopener">Open Claude setup →</a><span class="setup-note" id="connect-state">Keep this tab open while you finish setup in Claude. This page will detect the connection and show you the final one-time setting plus a dashboard link.</span></div><div class="guide-grid"><div class="guide-card"><div class="guide-copy"><span class="guide-num">1</span><h3>Confirm Link2AI and press Continue.</h3><p>The warning only means this custom connector came from an external link. Verify the name is <strong>${env().PUBLIC_BRAND_NAME}</strong> and the URL ends in <strong>/mcp</strong>, then continue.</p><span class="tiny-pill">Keep “Sign in now”</span></div><div class="guide-shot"><img loading="lazy" decoding="async" src="/guide/claude-add-connector.png" alt="Claude Add custom connector screen with Link2AI pre-filled"></div></div><div class="guide-card reverse"><div class="guide-shot"><img loading="lazy" decoding="async" src="/guide/claude-oauth.png" alt="Claude OAuth client options"><span class="guide-callout oauth"></span></div><div class="guide-copy"><span class="guide-num">2</span><h3>Choose “Register automatically”.</h3><p>Under <strong>OAuth client</strong>, choose <strong>Register automatically</strong>, then press <strong>Add</strong>. Do not choose “Use Claude’s published identity” for V2, and do not enter a client ID or secret.</p><span class="tiny-pill">This is the DCR path</span></div></div><div class="guide-card"><div class="guide-copy"><span class="guide-num">3</span><h3>Sign in to Link2AI and return to Claude.</h3><p>Create or sign in to your <strong>${env().PUBLIC_BRAND_NAME}</strong> account with email and password. The same account keeps your trial, usage and paid plan attached to you across browsers and devices. Claude then finishes the OAuth connection automatically.</p><p class="micro">The founding trial gives you 10 processing units to prove the workflow. Failed or unsupported processing uses 0 units.</p></div><div class="guide-shot" style="min-height:280px;display:grid;place-items:center;padding:28px"><div style="max-width:360px;width:100%;background:white;border:1px solid var(--line);border-radius:20px;padding:26px;box-shadow:0 16px 45px rgba(31,26,44,.08)"><span class="badge"><span class="badge-dot"></span>Free founding trial</span><h3 style="font-size:27px;margin:18px 0 9px">One account, then back to Claude.</h3><p style="color:var(--muted);line-height:1.55">Email + password. No card required for the free trial.</p><span class="btn purple" style="width:100%;margin-top:10px">Create account / Sign in</span></div></div></div><div class="guide-card reverse"><div class="guide-shot"><img loading="lazy" decoding="async" src="/guide/claude-tool-access.png" alt="Claude Tool access menu with Tools already loaded selected"><span class="guide-callout tools"></span></div><div class="guide-copy"><span class="guide-num">4</span><h3>Set Tool access to “Tools already loaded”.</h3><p>Claude currently defaults to <strong>Load tools when needed</strong>. For Link2AI’s normal “paste a link and ask” flow, switch this once: <strong>+ → Connectors → Tool access → Tools already loaded</strong>.</p><p class="micro">This is a Claude setting. Link2AI cannot change it remotely. If you leave the default on, Claude may answer that it cannot read the link without ever loading Link2AI.</p><span class="tiny-pill">Required once for reliable auto-use</span></div></div></div><div class="why-write"><strong>Why Claude may label “Read link content” as a write/delete tool:</strong> starting a read creates a Link2AI processing job and reserves usage quota. It does <strong>not</strong> edit or delete the source link, your Claude chats, or your files.</div><div class="manual"><details><summary>Optional: make future link reads more hands-off</summary><div class="guide-card reverse" style="margin-top:15px"><div class="guide-shot"><img loading="lazy" decoding="async" src="/guide/claude-permissions.png" alt="Claude Link2AI tool permissions"><span class="guide-callout allow"></span></div><div class="guide-copy"><h3>Permission behavior can vary by Claude session.</h3><p>If Claude asks before using <strong>Read link content</strong>, choose <strong>Always allow</strong> if you do not want to approve every link. If Claude does not show a permission popup, you do not need to hunt for one.</p></div></div></details></div><div class="manual"><details><summary>If the pre-filled button does not work, use the manual fallback</summary><div class="manual-grid"><div class="field"><label>Name</label><code>${env().PUBLIC_BRAND_NAME}</code></div><div class="field"><label>Remote MCP server URL</label><code id="mcp-address">${env().PUBLIC_BASE_URL}/mcp</code><button class="copybtn" type="button" onclick="navigator.clipboard.writeText('${env().PUBLIC_BASE_URL}/mcp').then(()=>this.textContent='Copied ✓')">Copy URL</button></div></div><p class="micro">Authentication: <strong>Sign in now</strong>. OAuth client: <strong>Register automatically</strong>. Leave client secret blank.</p></details></div></div><div id="setup-complete" hidden class="coming" style="margin-bottom:16px"><div><strong>Connected ✓ Finish the one-time Tool access setting.</strong><span>In Claude choose <strong>+ → Connectors → Tool access → Tools already loaded</strong>. After that, Link2AI can be available for natural link-only prompts.</span></div><a class="btn purple sm" href="/account">Done → Dashboard</a></div><div class="coming"><div><strong>Then use Claude normally.</strong><span>Paste a supported public link and ask your real question. You should not need to say “use Link2AI”. Claude decides whether it needs the connector.</span></div><a class="btn alt sm" href="/support">Need help?</a></div><div class="coming" style="margin-top:12px"><div><strong>Your first 30-second test</strong><span>Open a new Claude chat, paste one public link you already know, and ask a question that depends on the source. Try: “What are the main claims in this video?” or “What are people disagreeing about in this Reddit thread?”</span></div><a class="btn alt sm" href="/#examples">See examples</a></div><p class="micro" style="margin-top:18px">V2 reads spoken/caption text from supported videos plus public text from posts, discussions, webpages, GitHub issues/PRs and text-layer PDFs. Visual-only information such as image-only text, scanned documents, layout, gestures, diagrams and before/after pairings may not be available yet.</p></section><script>(()=>{const button=document.getElementById('claude-install');const state=document.getElementById('connect-state');let since=Number(sessionStorage.getItem('link2ai_connect_started')||0);let timer=null;const check=async()=>{if(!since)return;try{const response=await fetch('/api/connect/status?since='+encodeURIComponent(String(since)),{cache:'no-store',credentials:'same-origin'});if(!response.ok)return;const data=await response.json();if(data.connected){if(state)state.textContent='Connected ✓ One last Claude setting: + → Connectors → Tool access → Tools already loaded. Then open your dashboard.';clearInterval(timer);const done=document.getElementById('setup-complete');if(done)done.hidden=false;return;}if(data.authenticated&&state)state.textContent='Signed in. Finish the last Claude authorization step. This page will keep checking for the connection.';}catch{}};button?.addEventListener('click',()=>{since=Date.now();sessionStorage.setItem('link2ai_connect_started',String(since));if(state)state.textContent='Claude opened in a new tab. Finish setup there; keep this page open and Link2AI will confirm here when the connection is detected.';clearInterval(timer);timer=setInterval(check,1500);setTimeout(check,500);});if(since){timer=setInterval(check,1500);check();}})();</script></main>`, `Add ${env().PUBLIC_BRAND_NAME} to Claude`, `/connect`));});

app.get('/api/connect/status',async(req,reply)=>{
  const user=await userFromSessionCookie(req.headers.cookie);
  if(!user)return reply.send({authenticated:false,connected:false});
  const q=req.query as {since?:string};
  const rawSince=Number(q?.since??0);
  const since=Number.isFinite(rawSince)&&rawSince>0?new Date(rawSince):new Date(Date.now());
  const r=await pool.query<{connected:boolean}>(
    `SELECT (
       EXISTS(SELECT 1 FROM oauth_access_tokens WHERE user_id=$1 AND revoked_at IS NULL AND expires_at>now() AND created_at>$2)
       OR EXISTS(SELECT 1 FROM oauth_refresh_tokens WHERE user_id=$1 AND revoked_at IS NULL AND expires_at>now() AND created_at>$2)
     ) AS connected`,
    [user.id,since]
  );
  return reply.send({authenticated:true,connected:Boolean(r.rows[0]?.connected)});
});


function founderEscape(value:unknown):string{
  return String(value??'').replace(/[&<>\"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'\"':"&quot;","'":"&#39;"}[ch]??ch));
}
function founderTime(value:unknown):string{
  if(!value)return '—';
  const d=new Date(String(value));
  if(Number.isNaN(d.getTime()))return '—';
  return new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(d);
}
function founderNum(value:unknown):number{return Number(value??0)||0;}
function founderPct(part:number,total:number):string{return total>0?`${Math.round((part/total)*100)}%`:'0%';}
function founderUnits(seconds:unknown):string{
  const n=founderNum(seconds)/60;
  return n>=100?`${Math.round(n)}`:n.toFixed(n>=10?1:2).replace(/\\.00$/,'').replace(/(\\.\\d)0$/,'$1');
}
function founderPlanLabel(value:unknown):string{
  const v=String(value??'');
  return ({trial:'試用',basic:'Basic',pro:'Pro'} as Record<string,string>)[v]??v;
}
function founderAccountStatusLabel(value:unknown):string{
  const v=String(value??'');
  return ({active:'正常',past_due:'付款逾期',canceled:'已取消',disabled:'已停用'} as Record<string,string>)[v]??v;
}
function founderJobStatusLabel(value:unknown):string{
  const v=String(value??'');
  return ({queued:'排隊中',processing:'處理中',completed:'已完成',failed:'失敗',awaiting_payment:'等待付款',pending:'等待中'} as Record<string,string>)[v]??v;
}
function founderActionLabel(value:unknown):string{
  const v=String(value??'');
  return ({account_update:'帳號調整'} as Record<string,string>)[v]??v;
}
function founderShell(body:string,title=`${env().PUBLIC_BRAND_NAME} 後台`){
  const supportEmail=env().SUPPORT_EMAIL?.trim();
  return `<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>${title}</title><link rel="icon" href="/logo.svg"><style>${siteCss}</style></head><body><div class="wrap"><nav><a class="brand" href="/"><img src="/logo.svg" alt=""><span>${env().PUBLIC_BRAND_NAME}</span></a><div class="navlinks"><a class="hide-sm" href="/">首頁</a><a class="hide-sm" href="/pricing">方案</a><a class="hide-sm" href="/support">客服</a><a class="btn sm purple" href="/connect">加到 Claude</a></div></nav>${body}<footer><span>© 2026 ${env().PUBLIC_BRAND_NAME}</span><span class="legal-links"><a href="/privacy">隱私權</a> · <a href="/terms">服務條款</a> · <a href="/status">系統狀態</a> · <a href="/account">帳號</a>${supportEmail?` · <a href="mailto:${supportEmail}">客服：${supportEmail}</a>`:''}</span></footer></div></body></html>`;
}
function founderOriginOk(req:{headers:Record<string,string|string[]|undefined>}):boolean{
  let expected:string;
  try{expected=new URL(env().PUBLIC_BASE_URL).origin;}catch{return false;}
  const origin=Array.isArray(req.headers.origin)?req.headers.origin[0]:req.headers.origin;
  if(origin)return origin===expected;
  const referer=Array.isArray(req.headers.referer)?req.headers.referer[0]:req.headers.referer;
  if(!referer)return false;
  try{return new URL(referer).origin===expected;}catch{return false;}
}
async function founderUser(req:{headers:{cookie?:string}}){
  const founderEmail=env().FOUNDER_EMAIL?.trim().toLowerCase();
  if(!founderEmail)return null;
  const user=await userFromSessionCookie(req.headers.cookie);
  if(!user||(user.email??'').trim().toLowerCase()!==founderEmail)return null;
  return user;
}
