app.get('/founder',async(req,reply)=>{
  const founderEmail=env().FOUNDER_EMAIL?.trim().toLowerCase();
  if(!founderEmail)return reply.code(404).type('text/plain').send('Not found');
  const founder=await userFromSessionCookie(req.headers.cookie);
  if(!founder)return reply.redirect('/login?return_to=%2Ffounder');
  if((founder.email??'').trim().toLowerCase()!==founderEmail)return reply.code(404).type('text/plain').send('Not found');

  const q=String((req.query as {q?:string})?.q??'').trim().slice(0,160);
  const rawPage=Number((req.query as {page?:string})?.page??1);
  const page=Number.isFinite(rawPage)?Math.max(1,Math.floor(rawPage)):1;
  const pageSize=100;
  const offset=(page-1)*pageSize;

  const [summaryResult,recentJobsResult,platformResult,accountsCountResult,accountsResult,analyticsResult,topPagesResult]=await Promise.all([
    pool.query<{
      accounts_total:string;accounts_24h:string;accounts_7d:string;connected_total:string;activated_total:string;
      paid_total:string;basic_total:string;pro_total:string;links_total:string;links_24h:string;links_7d:string;
      seconds_total:string;seconds_7d:string;failed_24h:string;failed_7d:string;
    }>(`SELECT
      (SELECT COUNT(*) FROM users WHERE email IS NOT NULL)::text AS accounts_total,
      (SELECT COUNT(*) FROM users WHERE email IS NOT NULL AND created_at>now()-interval '24 hours')::text AS accounts_24h,
      (SELECT COUNT(*) FROM users WHERE email IS NOT NULL AND created_at>now()-interval '7 days')::text AS accounts_7d,
      (SELECT COUNT(DISTINCT user_id) FROM (
        SELECT user_id FROM oauth_access_tokens WHERE revoked_at IS NULL AND expires_at>now()
        UNION SELECT user_id FROM oauth_refresh_tokens WHERE revoked_at IS NULL AND expires_at>now()
      ) connected)::text AS connected_total,
      (SELECT COUNT(DISTINCT user_id) FROM usage_ledger)::text AS activated_total,
      (SELECT COUNT(*) FROM users WHERE plan IN ('basic','pro') AND account_status='active')::text AS paid_total,
      (SELECT COUNT(*) FROM users WHERE plan='basic' AND account_status='active')::text AS basic_total,
      (SELECT COUNT(*) FROM users WHERE plan='pro' AND account_status='active')::text AS pro_total,
      (SELECT COUNT(*) FROM usage_ledger)::text AS links_total,
      (SELECT COUNT(*) FROM usage_ledger WHERE created_at>now()-interval '24 hours')::text AS links_24h,
      (SELECT COUNT(*) FROM usage_ledger WHERE created_at>now()-interval '7 days')::text AS links_7d,
      COALESCE((SELECT SUM(seconds) FROM usage_ledger),0)::text AS seconds_total,
      COALESCE((SELECT SUM(seconds) FROM usage_ledger WHERE created_at>now()-interval '7 days'),0)::text AS seconds_7d,
      (SELECT COUNT(*) FROM transcript_jobs WHERE status='failed' AND created_at>now()-interval '24 hours')::text AS failed_24h,
      (SELECT COUNT(*) FROM transcript_jobs WHERE status='failed' AND created_at>now()-interval '7 days')::text AS failed_7d`),
    pool.query<{user_id:string;email:string|null;platform:string;status:string;duration_seconds:number|null;error_code:string|null;created_at:string}>(
      `SELECT j.user_id,u.email,j.platform,j.status,j.duration_seconds,j.error_code,j.created_at
       FROM transcript_jobs j LEFT JOIN users u ON u.id=j.user_id
       ORDER BY j.created_at DESC LIMIT 20`
    ),
    pool.query<{platform:string;count:string}>(
      `SELECT j.platform,COUNT(*)::text AS count FROM usage_ledger l JOIN transcript_jobs j ON j.id=l.job_id GROUP BY j.platform ORDER BY COUNT(*) DESC`
    ),
    pool.query<{count:string}>(`SELECT COUNT(*)::text AS count FROM users WHERE email IS NOT NULL AND ($1='' OR email ILIKE '%'||$1||'%')`,[q]),
    pool.query<{
      id:string;email:string;plan:string;account_status:string;trial_eligible:boolean;admin_bonus_seconds:number;admin_bonus_videos:number;created_at:string;
      connected:boolean;links:string;seconds:string;failed:string;last_activity:string|null;
    }>(`SELECT u.id,u.email,u.plan,u.account_status,u.trial_eligible,u.admin_bonus_seconds,u.admin_bonus_videos,u.created_at,
        (EXISTS(SELECT 1 FROM oauth_access_tokens a WHERE a.user_id=u.id AND a.revoked_at IS NULL AND a.expires_at>now())
         OR EXISTS(SELECT 1 FROM oauth_refresh_tokens r WHERE r.user_id=u.id AND r.revoked_at IS NULL AND r.expires_at>now())) AS connected,
        COALESCE(us.links,0)::text AS links,COALESCE(us.seconds,0)::text AS seconds,COALESCE(js.failed,0)::text AS failed,
        GREATEST(u.updated_at,us.last_used,js.last_job) AS last_activity
       FROM users u
       LEFT JOIN (SELECT user_id,COUNT(*) links,COALESCE(SUM(seconds),0) seconds,MAX(created_at) last_used FROM usage_ledger GROUP BY user_id) us ON us.user_id=u.id
       LEFT JOIN (SELECT user_id,COUNT(*) FILTER(WHERE status='failed') failed,MAX(created_at) last_job FROM transcript_jobs GROUP BY user_id) js ON js.user_id=u.id
       WHERE u.email IS NOT NULL AND ($1='' OR u.email ILIKE '%'||$1||'%')
       ORDER BY GREATEST(u.updated_at,us.last_used,js.last_job) DESC NULLS LAST,u.created_at DESC LIMIT $2 OFFSET $3`,[q,pageSize,offset]),
    pool.query<{
      visitors_total:string;visitors_24h:string;visitors_7d:string;pageviews_total:string;pageviews_24h:string;pageviews_7d:string;
      connect_visitors_total:string;signed_up_total:string;activated_visitors_total:string;non_founder_7d:string;
      historical_visitors_total:string;historical_pageviews_total:string;
    }>(`SELECT
      (SELECT COUNT(*) FROM website_visitors)::text AS visitors_total,
      (SELECT COUNT(DISTINCT visitor_id) FROM website_pageviews WHERE created_at>now()-interval '24 hours')::text AS visitors_24h,
      (SELECT COUNT(DISTINCT visitor_id) FROM website_pageviews WHERE created_at>now()-interval '7 days')::text AS visitors_7d,
      (SELECT COUNT(*) FROM website_pageviews)::text AS pageviews_total,
      (SELECT COUNT(*) FROM website_pageviews WHERE created_at>now()-interval '24 hours')::text AS pageviews_24h,
      (SELECT COUNT(*) FROM website_pageviews WHERE created_at>now()-interval '7 days')::text AS pageviews_7d,
      (SELECT COUNT(DISTINCT visitor_id) FROM website_pageviews WHERE path='/connect')::text AS connect_visitors_total,
      (SELECT COUNT(*) FROM website_visitors WHERE signed_up_at IS NOT NULL)::text AS signed_up_total,
      (SELECT COUNT(DISTINCT v.visitor_id) FROM website_visitors v JOIN usage_ledger l ON l.user_id=v.user_id WHERE v.signed_up_at IS NOT NULL)::text AS activated_visitors_total,
      (SELECT COUNT(*) FROM website_visitors v LEFT JOIN users u ON u.id=v.user_id WHERE v.last_seen_at>now()-interval '7 days' AND COALESCE(lower(u.email),'')<>$1)::text AS non_founder_7d,
      (SELECT COUNT(*) FROM website_visitors WHERE analytics_source='historical_backfill')::text AS historical_visitors_total,
      (SELECT COUNT(*) FROM website_pageviews WHERE source_key IS NOT NULL)::text AS historical_pageviews_total`,[founderEmail]),
    pool.query<{path:string;views:string;visitors:string}>(
      `SELECT path,COUNT(*)::text AS views,COUNT(DISTINCT visitor_id)::text AS visitors
       FROM website_pageviews WHERE created_at>now()-interval '7 days'
       GROUP BY path ORDER BY COUNT(*) DESC,COUNT(DISTINCT visitor_id) DESC LIMIT 10`
    )
  ]);

  const m=summaryResult.rows[0];
  const accounts=founderNum(m?.accounts_total),connected=founderNum(m?.connected_total),activated=founderNum(m?.activated_total),paid=founderNum(m?.paid_total);
  const links=founderNum(m?.links_total),seconds=founderNum(m?.seconds_total);
  const a=analyticsResult.rows[0];
  const visitors=founderNum(a?.visitors_total),visitorSignups=founderNum(a?.signed_up_total),visitorActivated=founderNum(a?.activated_visitors_total),connectVisitors=founderNum(a?.connect_visitors_total);
  const topPages=topPagesResult.rows.map(row=>`<tr><td class="fd-email">${founderEscape(row.path)}</td><td>${founderNum(row.visitors)}</td><td>${founderNum(row.views)}</td></tr>`).join('')||'<tr><td colspan="3">目前還沒有網站瀏覽紀錄。</td></tr>';
  const recentJobs=recentJobsResult.rows.map(row=>`<tr><td>${founderTime(row.created_at)}</td><td class="fd-email"><a href="/founder/user/${founderEscape(row.user_id)}">${founderEscape(row.email??'匿名')}</a></td><td>${founderEscape(row.platform)}</td><td><span class="fd-status ${row.status==='completed'?'ok':row.status==='failed'?'bad':'wait'}">${founderEscape(founderJobStatusLabel(row.status))}</span></td><td>${row.duration_seconds?`${Math.ceil(row.duration_seconds/60)} 分鐘`:'—'}</td><td>${founderEscape(row.error_code??'—')}</td></tr>`).join('')||'<tr><td colspan="6">目前還沒有工作紀錄。</td></tr>';
  const platforms=platformResult.rows.map(row=>`<span class="fd-chip">${founderEscape(row.platform)} · ${founderNum(row.count)}</span>`).join('')||'<span class="fd-chip">目前還沒有成功連結</span>';
  const totalMatched=founderNum(accountsCountResult.rows[0]?.count);
  const totalPages=Math.max(1,Math.ceil(totalMatched/pageSize));
  const accountRows=accountsResult.rows.map(row=>`<tr><td class="fd-email"><a href="/founder/user/${founderEscape(row.id)}">${founderEscape(row.email)}</a></td><td>${founderEscape(founderPlanLabel(row.plan))}</td><td>${founderEscape(founderAccountStatusLabel(row.account_status))}</td><td>${row.trial_eligible?'是':'否'}</td><td>${row.connected?'✓':'—'}</td><td>${founderNum(row.links)}</td><td>${founderUnits(row.seconds)}</td><td>${founderNum(row.failed)}</td><td>${founderTime(row.last_activity)}</td><td><a class="btn alt sm" href="/founder/user/${founderEscape(row.id)}">管理</a></td></tr>`).join('')||'<tr><td colspan="10">找不到符合的帳號。</td></tr>';
  const searchValue=founderEscape(q);
  const querySuffix=q?`&q=${encodeURIComponent(q)}`:'';
  const prev=page>1?`<a class="btn alt sm" href="/founder?page=${page-1}${querySuffix}">← 上一頁</a>`:'';
  const next=page<totalPages?`<a class="btn alt sm" href="/founder?page=${page+1}${querySuffix}">下一頁 →</a>`:'';

  const html=`<main class="fd">${founderCss()}<div class="fd-head"><div><span class="badge"><span class="badge-dot"></span>Founder 私人後台</span><h1>Link2AI 後台</h1><p class="fd-sub">網站流量、產品使用情況與帳號管理。完整 Email 只會顯示在這裡。</p></div><a class="btn alt sm" href="/founder">重新整理</a></div>
    <section class="fd-grid">
      <div class="fd-card"><div class="fd-label">不重複訪客</div><div class="fd-value">${visitors}</div><div class="fd-note">今天 +${founderNum(a?.visitors_24h)} · 7 天內 ${founderNum(a?.visitors_7d)} · 歷史回補 ${founderNum(a?.historical_visitors_total)}</div></div>
      <div class="fd-card"><div class="fd-label">頁面瀏覽次數</div><div class="fd-value">${founderNum(a?.pageviews_total)}</div><div class="fd-note">今天 +${founderNum(a?.pageviews_24h)} · 7 天內 ${founderNum(a?.pageviews_7d)} · 歷史回補 ${founderNum(a?.historical_pageviews_total)}</div></div>
      <div class="fd-card"><div class="fd-label">訪客註冊數</div><div class="fd-value">${visitorSignups}</div><div class="fd-note">佔追蹤訪客 ${founderPct(visitorSignups,Math.max(visitors,1))}</div></div>
      <div class="fd-card"><div class="fd-label">非 Founder 訪客</div><div class="fd-value">${founderNum(a?.non_founder_7d)}</div><div class="fd-note">最近 7 天曾造訪</div></div>
      <div class="fd-card"><div class="fd-label">帳號數</div><div class="fd-value">${accounts}</div><div class="fd-note">今天 +${founderNum(m?.accounts_24h)} · 7 天內 +${founderNum(m?.accounts_7d)}</div></div>
      <div class="fd-card"><div class="fd-label">已連接 Claude</div><div class="fd-value">${connected}</div><div class="fd-note">佔帳號 ${founderPct(connected,accounts)}</div></div>
      <div class="fd-card"><div class="fd-label">成功連結</div><div class="fd-value">${links}</div><div class="fd-note">今天 +${founderNum(m?.links_24h)} · 7 天內 +${founderNum(m?.links_7d)}</div></div>
      <div class="fd-card"><div class="fd-label">付費使用者</div><div class="fd-value">${paid}</div><div class="fd-note">Basic ${founderNum(m?.basic_total)} · Pro ${founderNum(m?.pro_total)}</div></div>
      <div class="fd-card"><div class="fd-label">已啟用使用者</div><div class="fd-value">${activated}</div><div class="fd-note">至少成功 1 個連結 · 佔帳號 ${founderPct(activated,accounts)}</div></div>
      <div class="fd-card"><div class="fd-label">已處理內容</div><div class="fd-value">${founderUnits(seconds)} 單位</div><div class="fd-note">7 天內 ${founderUnits(m?.seconds_7d)} 單位</div></div>
      <div class="fd-card"><div class="fd-label">失敗工作</div><div class="fd-value">${founderNum(m?.failed_24h)}</div><div class="fd-note">今天 · 7 天內 ${founderNum(m?.failed_7d)}</div></div>
      <div class="fd-card"><div class="fd-label">平台</div><div class="fd-chips" style="margin-top:10px">${platforms}</div></div>
    </section>
    <section><div class="fd-label" style="margin-bottom:8px">網站轉換漏斗 · 已回補可辨識的舊 Railway 流量</div><div class="fd-funnel"><div class="fd-step"><b>${visitors}</b><span>不重複訪客</span></div><div class="fd-step"><b>${connectVisitors}</b><span>開啟設定頁 · ${founderPct(connectVisitors,Math.max(visitors,1))}</span></div><div class="fd-step"><b>${visitorSignups}</b><span>完成註冊 · ${founderPct(visitorSignups,Math.max(visitors,1))}</span></div><div class="fd-step"><b>${visitorActivated}</b><span>成功啟用 · 佔註冊者 ${founderPct(visitorActivated,Math.max(visitorSignups,1))}</span></div></div></section>
    <section class="fd-panel"><div class="fd-panel-head"><div><h2>熱門網站頁面</h2><div class="fd-note">最近 7 天 · 匿名第一方統計</div></div><span class="fd-label">不儲存 IP</span></div><div class="fd-scroll"><table class="fd-table" style="min-width:520px"><thead><tr><th>頁面</th><th>不重複訪客</th><th>瀏覽次數</th></tr></thead><tbody>${topPages}</tbody></table></div></section>
    <section><div class="fd-label" style="margin-bottom:8px">產品轉換漏斗</div><div class="fd-funnel"><div class="fd-step"><b>${accounts}</b><span>帳號</span></div><div class="fd-step"><b>${connected}</b><span>已連接 Claude · ${founderPct(connected,accounts)}</span></div><div class="fd-step"><b>${activated}</b><span>首次成功連結 · ${founderPct(activated,accounts)}</span></div><div class="fd-step"><b>${paid}</b><span>付費 · 佔已啟用使用者 ${founderPct(paid,Math.max(activated,1))}</span></div></div></section>
    <section class="fd-panel"><div class="fd-panel-head"><div><h2>所有帳號</h2><div class="fd-note">${totalMatched} 筆符合 · 第 ${page}／${totalPages} 頁</div></div><form method="get" action="/founder" class="fd-tools"><input class="fd-input" type="search" name="q" value="${searchValue}" placeholder="搜尋 Email"><button class="btn alt sm" type="submit">搜尋</button>${q?'<a class="btn alt sm" href="/founder">清除</a>':''}</form></div><div class="fd-scroll"><table class="fd-table"><thead><tr><th>Email</th><th>方案</th><th>狀態</th><th>試用資格</th><th>Claude</th><th>成功連結</th><th>Processing units</th><th>失敗</th><th>最後活動</th><th></th></tr></thead><tbody>${accountRows}</tbody></table></div><div class="fd-panel-head"><span class="fd-label">每頁 100 筆</span><div class="fd-nav">${prev}${next}</div></div></section>
    <section class="fd-panel"><div class="fd-panel-head"><h2>最近工作</h2><span class="fd-label">最近 20 筆</span></div><div class="fd-scroll"><table class="fd-table"><thead><tr><th>時間</th><th>Email</th><th>平台</th><th>狀態</th><th>長度</th><th>錯誤</th></tr></thead><tbody>${recentJobs}</tbody></table></div></section>
    <div class="fd-warning">Analytics 上線前的可辨識網站瀏覽已從 Railway 舊 HTTP logs 回補。歷史不重複訪客是匿名估算值；明顯 bot／爬蟲已排除。回補資料只保存匿名識別碼、頁面與時間，不保存原始 IP 或 User-Agent，也不推測無法確認的歷史註冊歸因。</div><div class="fd-warning">後台調整不會刪除使用紀錄。額外額度會加在原方案上；手動修改方案後，之後仍可能被 Lemon Squeezy 的正式訂閱 webhook 更新。</div>
    <p class="fd-private">私人頁面。只有登入 Email 與 FOUNDER_EMAIL 相同的帳號可以開啟。</p></main>`;
  return reply.type('text/html').send(founderShell(html,`${env().PUBLIC_BRAND_NAME} 後台`));
});

app.get('/founder/user/:id',async(req,reply)=>{
  const founderEmail=env().FOUNDER_EMAIL?.trim().toLowerCase();
  if(!founderEmail)return reply.code(404).type('text/plain').send('Not found');
  const founder=await userFromSessionCookie(req.headers.cookie);
  if(!founder)return reply.redirect('/login?return_to=%2Ffounder');
  if((founder.email??'').trim().toLowerCase()!==founderEmail)return reply.code(404).type('text/plain').send('Not found');
  const targetId=String((req.params as {id?:string})?.id??'');
  const accountResult=await pool.query<{
    id:string;email:string|null;plan:string;account_status:string;trial_eligible:boolean;admin_bonus_seconds:number;admin_bonus_videos:number;created_at:string;updated_at:string;connected:boolean;
  }>(`SELECT u.id,u.email,u.plan,u.account_status,u.trial_eligible,u.admin_bonus_seconds,u.admin_bonus_videos,u.created_at,u.updated_at,
      (EXISTS(SELECT 1 FROM oauth_access_tokens a WHERE a.user_id=u.id AND a.revoked_at IS NULL AND a.expires_at>now())
       OR EXISTS(SELECT 1 FROM oauth_refresh_tokens r WHERE r.user_id=u.id AND r.revoked_at IS NULL AND r.expires_at>now())) AS connected
      FROM users u WHERE u.id=$1`,[targetId]);
  if(!accountResult.rowCount)return reply.code(404).type('text/plain').send('Not found');
  const account=accountResult.rows[0];
  const [usage,allTimeResult,jobsResult,auditResult]=await Promise.all([
    getUsageSnapshot(targetId),
    pool.query<{links:string;seconds:string;failed:string;last_job:string|null}>(`SELECT
      (SELECT COUNT(*) FROM usage_ledger WHERE user_id=$1)::text links,
      COALESCE((SELECT SUM(seconds) FROM usage_ledger WHERE user_id=$1),0)::text seconds,
      (SELECT COUNT(*) FROM transcript_jobs WHERE user_id=$1 AND status='failed')::text failed,
      (SELECT MAX(created_at) FROM transcript_jobs WHERE user_id=$1) last_job`,[targetId]),
    pool.query<{id:string;platform:string;status:string;duration_seconds:number|null;error_code:string|null;created_at:string}>(`SELECT id,platform,status,duration_seconds,error_code,created_at FROM transcript_jobs WHERE user_id=$1 ORDER BY created_at DESC LIMIT 30`,[targetId]),
    pool.query<{action:string;before_state:unknown;after_state:unknown;created_at:string}>(`SELECT action,before_state,after_state,created_at FROM founder_admin_events WHERE target_user_id=$1 ORDER BY created_at DESC LIMIT 10`,[targetId])
  ]);
  const a=allTimeResult.rows[0];
  const flash=String((req.query as {saved?:string;error?:string})?.saved??'')==='1'?'<div class="fd-okflash">已儲存。</div>':String((req.query as {error?:string})?.error??'')?`<div class="fd-badflash">${founderEscape((req.query as {error?:string}).error)}</div>`:'';
  const jobRows=jobsResult.rows.map(row=>`<tr><td>${founderTime(row.created_at)}</td><td>${founderEscape(row.platform)}</td><td>${founderEscape(founderJobStatusLabel(row.status))}</td><td>${row.duration_seconds?`${Math.ceil(row.duration_seconds/60)} 分鐘`:'—'}</td><td>${founderEscape(row.error_code??'—')}</td><td class="fd-email">${founderEscape(row.id)}</td></tr>`).join('')||'<tr><td colspan="6">目前還沒有工作紀錄。</td></tr>';
  const auditRows=auditResult.rows.map(row=>`<tr><td>${founderTime(row.created_at)}</td><td>${founderEscape(founderActionLabel(row.action))}</td><td class="fd-muted">${founderEscape(JSON.stringify(row.after_state??{}))}</td></tr>`).join('')||'<tr><td colspan="3">目前還沒有 Founder 調整紀錄。</td></tr>';
  const self=targetId===founder.id;
  const html=`<main class="fd">${founderCss()}<div class="fd-head"><div><a href="/founder" class="fd-note">← 所有帳號</a><h1 style="font-size:clamp(30px,5vw,52px)">${founderEscape(account.email??'匿名')}</h1><p class="fd-sub fd-email">${founderEscape(account.id)}</p></div><a class="btn alt sm" href="/founder/user/${founderEscape(targetId)}">重新整理</a></div>${flash}
    <section class="fd-grid">
      <div class="fd-card"><div class="fd-label">方案</div><div class="fd-value" style="font-size:26px">${founderEscape(founderPlanLabel(account.plan))}</div><div class="fd-note">${founderEscape(founderAccountStatusLabel(account.account_status))}</div></div>
      <div class="fd-card"><div class="fd-label">目前用量</div><div class="fd-value" style="font-size:26px">${founderUnits(usage.used_seconds)} 單位</div><div class="fd-note">本期上限 ${founderUnits(usage.limit_seconds)} 單位 · 連結數不設固定上限</div></div>
      <div class="fd-card"><div class="fd-label">剩餘額度</div><div class="fd-value" style="font-size:26px">${founderUnits(usage.remaining_seconds)} 單位</div><div class="fd-note">本期到 ${founderTime(usage.period_end)}</div></div>
      <div class="fd-card"><div class="fd-label">Claude</div><div class="fd-value" style="font-size:26px">${account.connected?'已連接':'—'}</div><div class="fd-note">試用資格：${account.trial_eligible?'有':'無'}</div></div>
      <div class="fd-card"><div class="fd-label">累計成功連結</div><div class="fd-value">${founderNum(a?.links)}</div><div class="fd-note">累計 ${founderUnits(a?.seconds)} processing units</div></div>
      <div class="fd-card"><div class="fd-label">失敗工作</div><div class="fd-value">${founderNum(a?.failed)}</div><div class="fd-note">最後工作 ${founderTime(a?.last_job)}</div></div>
      <div class="fd-card"><div class="fd-label">額外額度</div><div class="fd-value" style="font-size:26px">${founderUnits(account.admin_bonus_seconds)} 單位</div><div class="fd-note">Legacy link bonus ${founderNum(account.admin_bonus_videos)}（V2 不再限制連結數）</div></div>
      <div class="fd-card"><div class="fd-label">建立時間</div><div class="fd-value" style="font-size:20px">${founderTime(account.created_at)}</div><div class="fd-note">更新於 ${founderTime(account.updated_at)}</div></div>
    </section>
    <section class="fd-panel"><div class="fd-panel-head"><div><h2>調整帳號</h2><div class="fd-note">使用紀錄不會被刪除。</div></div></div><div style="padding:18px"><form method="post" action="/founder/user/${founderEscape(targetId)}/update"><div class="fd-form-grid">
      <div class="fd-field"><label>方案</label><select class="fd-select" name="plan"><option value="trial" ${account.plan==='trial'?'selected':''}>試用</option><option value="basic" ${account.plan==='basic'?'selected':''}>Basic</option><option value="pro" ${account.plan==='pro'?'selected':''}>Pro</option></select><small>手動調整方案；之後 Lemon Squeezy webhook 仍可能依正式訂閱狀態更新。</small></div>
      <div class="fd-field"><label>帳號狀態</label><select class="fd-select" name="account_status"><option value="active" ${account.account_status==='active'?'selected':''}>正常</option><option value="past_due" ${account.account_status==='past_due'?'selected':''}>付款逾期</option><option value="canceled" ${account.account_status==='canceled'?'selected':''}>已取消</option><option value="disabled" ${account.account_status==='disabled'?'selected':''}>已停用</option></select><small>停用後會阻擋網站登入、OAuth 與新的處理工作。${self?' 你不能在這裡停用自己的 Founder 帳號。':''}</small></div>
      <div class="fd-field"><label>試用資格</label><select class="fd-select" name="trial_eligible"><option value="true" ${account.trial_eligible?'selected':''}>可試用</option><option value="false" ${!account.trial_eligible?'selected':''}>不可試用</option></select><small>只有帳號目前是試用方案時才會生效。</small></div>
      <div class="fd-field"><label>額外 processing units</label><input class="fd-input" type="number" name="bonus_minutes" min="0" max="100000" step="1" value="${Math.floor(founderNum(account.admin_bonus_seconds)/60)}"><small>直接加在原方案額度上，不會更動既有使用紀錄。</small></div>
      <div class="fd-field"><label>額外連結數</label><input class="fd-input" type="number" name="bonus_links" min="0" max="100000" step="1" value="${founderNum(account.admin_bonus_videos)}"><small>Legacy 欄位，目前 V2 不再以連結數限制方案；保留值只為相容舊資料。</small></div>
    </div><div class="fd-actions"><button class="btn purple" type="submit">儲存變更</button><a class="btn alt" href="/founder">返回</a></div></form></div></section>
    <section class="fd-panel"><div class="fd-panel-head"><h2>最近工作</h2><span class="fd-label">最近 30 筆</span></div><div class="fd-scroll"><table class="fd-table"><thead><tr><th>時間</th><th>平台</th><th>狀態</th><th>長度</th><th>錯誤</th><th>工作 ID</th></tr></thead><tbody>${jobRows}</tbody></table></div></section>
    <section class="fd-panel"><div class="fd-panel-head"><h2>Founder 調整紀錄</h2><span class="fd-label">最近 10 筆</span></div><div class="fd-scroll"><table class="fd-table"><thead><tr><th>時間</th><th>動作</th><th>新狀態</th></tr></thead><tbody>${auditRows}</tbody></table></div></section>
    <p class="fd-private">完整 Email 與帳號控制只會顯示給 FOUNDER_EMAIL。</p></main>`;
  return reply.type('text/html').send(founderShell(html,`${env().PUBLIC_BRAND_NAME} 帳號管理`));
});

app.post('/founder/user/:id/update',async(req,reply)=>{
  const founderEmail=env().FOUNDER_EMAIL?.trim().toLowerCase();
  if(!founderEmail)return reply.code(404).type('text/plain').send('Not found');
  const founder=await userFromSessionCookie(req.headers.cookie);
  if(!founder||(founder.email??'').trim().toLowerCase()!==founderEmail)return reply.code(404).type('text/plain').send('Not found');
  if(!founderOriginOk(req as unknown as {headers:Record<string,string|string[]|undefined>}))return reply.code(403).type('text/plain').send('Invalid origin');
  const targetId=String((req.params as {id?:string})?.id??'');
  const body=(req.body??{}) as Record<string,unknown>;
  const plan=String(body.plan??'');
  const accountStatus=String(body.account_status??'');
  const trialEligible=String(body.trial_eligible??'')==='true';
  const bonusMinutes=Number(body.bonus_minutes??0);
  const bonusLinks=Number(body.bonus_links??0);
  if(!['trial','basic','pro'].includes(plan)||!['active','past_due','canceled','disabled'].includes(accountStatus)||!Number.isInteger(bonusMinutes)||bonusMinutes<0||bonusMinutes>100000||!Number.isInteger(bonusLinks)||bonusLinks<0||bonusLinks>100000){
    return reply.redirect(`/founder/user/${encodeURIComponent(targetId)}?error=${encodeURIComponent('帳號設定格式不正確。')}`);
  }
  if(targetId===founder.id&&accountStatus==='disabled')return reply.redirect(`/founder/user/${encodeURIComponent(targetId)}?error=${encodeURIComponent('不能從 Founder 後台停用自己的帳號。')}`);
  const client=await pool.connect();
  try{
    await client.query('BEGIN');
    const before=await client.query<{id:string;email:string|null;plan:string;account_status:string;trial_eligible:boolean;admin_bonus_seconds:number;admin_bonus_videos:number}>(`SELECT id,email,plan,account_status,trial_eligible,admin_bonus_seconds,admin_bonus_videos FROM users WHERE id=$1 FOR UPDATE`,[targetId]);
    if(!before.rowCount){await client.query('ROLLBACK');return reply.code(404).type('text/plain').send('Not found');}
    const after=await client.query<{id:string;email:string|null;plan:string;account_status:string;trial_eligible:boolean;admin_bonus_seconds:number;admin_bonus_videos:number}>(`UPDATE users SET plan=$2,account_status=$3,trial_eligible=$4,admin_bonus_seconds=$5,admin_bonus_videos=$6,updated_at=now() WHERE id=$1 RETURNING id,email,plan,account_status,trial_eligible,admin_bonus_seconds,admin_bonus_videos`,[targetId,plan,accountStatus,trialEligible,bonusMinutes*60,bonusLinks]);
    await client.query(`INSERT INTO founder_admin_events(founder_user_id,target_user_id,action,before_state,after_state) VALUES($1,$2,'account_update',$3::jsonb,$4::jsonb)`,[founder.id,targetId,JSON.stringify(before.rows[0]),JSON.stringify(after.rows[0])]);
    await client.query('COMMIT');
    return reply.redirect(`/founder/user/${encodeURIComponent(targetId)}?saved=1`);
  }catch(err){
    await client.query('ROLLBACK');
    app.log.error(err);
    return reply.redirect(`/founder/user/${encodeURIComponent(targetId)}?error=${encodeURIComponent('儲存失敗。')}`);
  }finally{client.release();}
});


app.get('/support',async(req,reply)=>{await trackWebsiteVisit(req,reply,'/support');return reply.type('text/html').send(siteShell(`<main id="main-content"><section class="connect-hero" style="text-align:left;margin-left:0"><span class="badge"><span class="badge-dot"></span>Support</span><h1>Something got in the way?</h1><p>Start with the three checks below. They cover the most common causes in order: connection setup, link scope, then temporary third-party extraction problems.</p><div class="actions">${env().SUPPORT_EMAIL?`<a class="btn purple" href="mailto:${env().SUPPORT_EMAIL}">Email support →</a>`:''}<a class="btn alt" href="/connect">Open setup guide</a><a class="btn alt" href="/status">Check API status</a></div>${env().SUPPORT_EMAIL?`<p class="micro">Support email: <a href="mailto:${env().SUPPORT_EMAIL}"><strong>${env().SUPPORT_EMAIL}</strong></a></p>`:''}</section><section class="support-grid"><div class="card"><div class="kicker">1 · Connection</div><h3>Claude cannot see Link2AI</h3><p>Reconnect from the setup page and finish OAuth plus Tool access. Automatic client registration is the recommended path, so users should not need to paste a client secret.</p></div><div class="card"><div class="kicker">2 · Link scope</div><h3>A public link did not process</h3><p>Confirm it is an individual supported public link, not a profile, feed, search page, private item, paywalled page or DRM-protected source. Unsupported, inaccessible or failed reads consume 0 processing units. Very large supported sources may return partial context with an explicit truncation notice.</p></div><div class="card"><div class="kicker">3 · Send useful context</div><h3>What to include in a support email</h3><p>Send your Link2AI account email, platform, public URL, exact error message and job ID if one is shown. Never send passwords, card numbers, private-account credentials or identity documents.</p></div></section><div class="scope-note" style="margin-bottom:70px"><div class="scope-icon">i</div><div><strong>The read succeeded, but the answer seems incomplete?</strong><p>Check whether Claude mentions that the source was truncated or partially processed. Large discussions, PRs, pages and PDFs can hit V2 safety budgets. That is different from a failed read: Link2AI returns the processed portion, marks it as partial, and charges only for what was successfully processed.</p></div></div></main>`, `${env().PUBLIC_BRAND_NAME} Support`, `/support`));});

